import pandas as pd
from dataretrieval import nwis

# Read station IDs
with open('/root/data/michigan_stations.txt') as f:
    station_ids = [line.strip() for line in f if line.strip()]

print(f"Total stations to download: {len(station_ids)}")

all_frames = []
failed = []

for site_id in station_ids:
    try:
        df, meta = nwis.get_iv(
            sites=site_id,
            start='2025-04-01',
            end='2025-04-07',
            parameterCd='00065'
        )
        if len(df) > 0:
            # Find gage height column
            gage_col = [c for c in df.columns if '00065' in str(c) and '_cd' not in str(c)]
            if gage_col:
                subset = df[[gage_col[0]]].copy()
                subset.columns = ['gage_height']
                subset['site_no'] = site_id
                all_frames.append(subset)
                print(f"  {site_id}: {len(subset)} records")
            else:
                print(f"  {site_id}: no gage height column found")
        else:
            print(f"  {site_id}: no data")
    except Exception as e:
        failed.append(site_id)
        print(f"  {site_id}: FAILED - {e}")

if all_frames:
    result = pd.concat(all_frames)
    result.to_csv('/root/data/usgs_water_levels.csv')
    print(f"\nSaved {len(result)} total records from {len(all_frames)} stations")
else:
    print("No data downloaded!")

if failed:
    print(f"Failed stations ({len(failed)}): {failed}")

